import sys

def max_bracketed_expression(expression):
    n = len(expression)
    dp = [[[0, 0] for _ in range(n)] for _ in range(n)]

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 1:
                dp[i][j][0] = dp[i][j][1] = int(expression[i])
            else:
                for k in range(i, j, 2):
                    left_add, left_mul = dp[i][k-1]
                    right_add, right_mul = dp[k+1][j]
                    op = expression[k]
                    if op == '+':
                        dp[i][j][0] = max(dp[i][j][0], left_add + right_add)
                        dp[i][j][1] = max(dp[i][j][1], left_add + right_mul, left_mul + right_add, left_mul + right_mul)
                    elif op == '*':
                        dp[i][j][0] = max(dp[i][j][0], left_add * right_add)
                        dp[i][j][1] = max(dp[i][j][1], left_add * right_mul, left_mul * right_add, left_mul * right_mul)

    return dp[0][n-1][1]

