    for i in range(0, n, 2):
        dp[i][i][0] = int(s[i])

    for length in range(3, n + 1, 2):
        for i in range(0, n - length + 1, 2):
            j = i + length - 1
            if s[j-1] == '+':
                for k in range(i, j, 2):
                    dp[i][j][0] = max(dp[i][j][0], dp[i][k][0] + dp[k+2][j][0])
                    dp[i][j][1] = max(dp[i][j][1], dp[i][k][1] + dp[k+2][j][0])
                    dp[i][j][1] = max(dp[i][j][1], dp[i][k][0] + dp[k+2][j][1])
            else:
                for k in range(i, j, 2):
                    dp[i][j][0] = max(dp[i][j][0], dp[i][k][0] * dp[k+2][j][0])
                    dp[i][j][1] = max(dp[i][j][1], dp[i][k][1] * dp[k+2][j][0])
                    dp[i][j][1] = max(dp[i][j][1], dp[i][k][0] * dp[k+2][j][1])

